65.text:
 Each module receives namespace as a parameter, keeping options scoped under config.<namespace>.*: { config, lib, namespace, ... }@args:
let
  cfg = config.${namespace}.my-module;
in
{
  options.${namespace}.my-module.enable = lib.mkEnableOption "my module";
  config = lib.mkIf cfg.enable { ... };
}

67.text:
 Create a lib/ directory under src to share functions across all modules: # lib/default.nix
{ lib, inputs, namespace }:
{
  keys = import ./keys.nix { inherit lib inputs namespace; };
  utils = import ./utils.nix { inherit lib inputs namespace; };
} Functions are accessible as lib.<namespace>.* in all modules, packages, shells, and checks: # packages/known-hosts/default.nix
{ pkgs, lib, namespace, ... }:
let
  inherit (lib.${namespace}) keys;
in
pkgs.writeText "known-hosts" (keys.generate { ... }) Subdirectories nest by default (lib.<namespace>.keys.foo). Set flattenLib = true to merge all submodules directly under the namespace (lib.<namespace>.foo). The lib/ directory supports both a root default.nix and recursive subdirectory discovery via findModules — both can coexist.

